    node notation: Concept "Notation";
    node diagram: Concept "Diagram";
    node obsidian: Concept "Obsidian plugin";
    node vscode: Concept "VS Code extension";
    node local: Concept "Local MCP server";
    node hosted: Concept "Hosted MCP server";
    node assistant: Concept "AI assistant";
    node notes: Concept "Your notes";
    node report: Concept "Quality Report";

    node rReads: Relation "reads";
    node rEnforces: Relation "enforces";
    node rRunsInside: Relation "runs inside";
    node rDescribes: Relation "describes";
    node rDefinesRules: Relation "defines the rules for";
    node rRenderIn: Relation "render diagrams in";
    node rUsedBy: Relation "are used by";
