    node rProduces: Relation "produces";
    node rDescribes2: Relation "critiques";
    node rReads2: Relation "reads";

    edge engine -> rReads;
    edge rReads -> vgl;

    edge engine -> rEnforces;
    edge rEnforces -> notation;

    edge engine -> rRunsInside;
    edge rRunsInside -> obsidian;
    edge rRunsInside -> vscode;
    edge rRunsInside -> local;
    edge rRunsInside -> hosted;

    edge vgl -> rDescribes;
    edge rDescribes -> diagram;

    edge notation -> rDefinesRules;
    edge rDefinesRules -> diagram;

    edge obsidian -> rRenderIn;
    edge vscode -> rRenderIn;
    edge rRenderIn -> notes;

    edge local -> rUsedBy;
    edge hosted -> rUsedBy;
    edge rUsedBy -> assistant;

    edge assistant -> rWrites;
    edge rWrites -> vgl;

    edge engine -> rProduces;
    edge rProduces -> report;

    edge report -> rDescribes2;
    edge rDescribes2 -> diagram;

    edge assistant -> rReads2;
    edge rReads2 -> report;
